#!/usr/bin/env python3

import argparse
import bson
import codecs
import pprint
import subprocess
import sys
from bson.json_util import dumps, CANONICAL_JSON_OPTIONS

def print_bson(bson_obj, as_json):
    &quot;&quot;&quot;Pretty print BSON object&quot;&quot;&quot;
    if as_json:
        return dumps(bson_obj, json_options=CANONICAL_JSON_OPTIONS)
    else:
        return pprint.pformat(bson_obj, indent=2).replace(&#039;\n&#039;, &#039;\n  &#039;)

def decode_index_file(wt_path, file_path, as_json=False, verbose=True):
    &quot;&quot;&quot;
    Decode a MongoDB WiredTiger index file and display its contents.

    Args:
        wt_path: Path to the &#039;wt&#039; utility binary
        file_path: Path to the .wt file to decode
        as_json: Output as JSON format
        verbose: Print detailed information
    &quot;&quot;&quot;
    try:
        # Execute wt dump command
        cmd = [wt_path, &quot;-r&quot;, &quot;dump&quot;, &quot;-x&quot;, file_path]
        if verbose:
            print(f&quot;Executing: {&#039; &#039;.join(cmd)}&quot;, file=sys.stderr)

        output = subprocess.check_output(cmd, universal_newlines=True)
        lines = output.splitlines()

        if verbose:
            print(f&quot;Total lines read: {len(lines)}&quot;, file=sys.stderr)

        # Find header and data sections
        header_end = -1
        data_start = -1

        for i, line in enumerate(lines):
            if line.strip() == &#039;Header&#039;:
                header_end = i
            if line.strip() == &#039;Data&#039;:
                data_start = i + 1
                break

        if verbose:
            print(f&quot;Header section: lines 0-{header_end}&quot;, file=sys.stderr)
            print(f&quot;Data section starts at: line {data_start}&quot;, file=sys.stderr)

        # Print header information
        if header_end &gt; 0:
            print(&quot;=&quot; * 80)
            print(&quot;INDEX FILE HEADER&quot;)
            print(&quot;=&quot; * 80)
            for i in range(1, header_end):
                print(f&quot;{lines[i]}&quot;)
            print()

        # Process data section - key-value pairs
        print(&quot;=&quot; * 80)
        print(&quot;INDEX DATA (KEY-VALUE PAIRS)&quot;)
        print(&quot;=&quot; * 80)

        if data_start &lt; 0:
            print(&quot;ERROR: No Data section found in file!&quot;)
            return

        processed = 0
        failed = 0
        i = data_start

        while i &lt; len(lines):
            # Each key-value pair takes 2 lines
            if i + 1 &gt;= len(lines):
                if lines[i].strip():
                    print(f&quot;\nWARNING: Incomplete pair at line {i}&quot;)
                    print(f&quot;Remaining line: {lines[i][:100]}&quot;)
                break

            key_hex = lines[i].strip()
            value_hex = lines[i + 1].strip()

            # Skip empty lines
            if not key_hex or not value_hex:
                i += 2
                continue

            try:
                # Decode hex to bytes
                key_bytes = codecs.decode(key_hex, &#039;hex&#039;)
                value_bytes = codecs.decode(value_hex, &#039;hex&#039;)

                # Try to decode BSON
                try:
                    value_bson = bson.decode_all(value_bytes)[0]
                except:
                    # If value is not BSON, just show as hex
                    value_bson = {&quot;_raw_hex&quot;: value_hex[:100] + (&quot;...&quot; if len(value_hex) &gt; 100 else &quot;&quot;)}

                # Try to decode key as BSON
                try:
                    key_bson = bson.decode_all(key_bytes)[0]
                    key_display = print_bson(key_bson, as_json)
                except:
                    # If key is not BSON, show as hex
                    key_display = key_hex[:100] + (&quot;...&quot; if len(key_hex) &gt; 100 else &quot;&quot;)

                # Print the pair
                print(f&quot;\n[Entry {processed + 1}]&quot;)
                print(f&quot;Key:&quot;)
                print(f&quot;  {key_display}&quot;)
                print(f&quot;Value:&quot;)
                print(f&quot;  {print_bson(value_bson, as_json)}&quot;)

                processed += 1

            except Exception as e:
                print(f&quot;\nERROR at line {i}: {e}&quot;)
                print(f&quot;  Key (first 100 chars): {key_hex[:100]}&quot;)
                print(f&quot;  Value (first 100 chars): {value_hex[:100]}&quot;)
                failed += 1

            i += 2

        # Summary
        print(&quot;\n&quot; + &quot;=&quot; * 80)
        print(f&quot;SUMMARY: {processed} entries decoded successfully, {failed} errors&quot;)
        print(&quot;=&quot; * 80)

    except subprocess.CalledProcessError as e:
        print(f&quot;ERROR executing wt utility: {e}&quot;, file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f&quot;ERROR: {e}&quot;, file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(
        prog=&#039;decode_mdb_index&#039;,
        description=&#039;Decode MongoDB WiredTiger index files and display their contents&#039;
    )
    parser.add_argument(&#039;-w&#039;, &#039;--wt-path&#039;,
