    constructor() {
        this.promise = new Promise&lt;T&gt;((resolve, reject) =&gt; {
            this.resolve = resolve;
            this.reject = reject;
        });
    }
}

// Usage
async function fetchUser(id: number): Promise&lt;{ id: number; name: string }&gt; {
