        if (this.privIsDisposed) {
            throw new Error(&quot;Cannot use disposed connection&quot;);
        }

        if (!this.connection.isOpen) {
            throw new Error(&quot;Connection is not open&quot;);
        }

        // Execute query
        return { result: &quot;data&quot; };
    }
}

