class Heap {
  constructor(compare) {
    this.data = [];
    this.compare = compare; // (a, b) =&gt; a &lt; b for MinHeap, a &gt; b for MaxHeap
  }

  parent(i) { return Math.floor((i - 1) / 2); }
  left(i) { return 2 * i + 1; }
  right(i) { return 2 * i + 2; }

  swap(i, j) {
    [this.data[i], this.data[j]] = [this.data[j], this.data[i]];
  }

  push(value) {
    this.data.push(value);
    this.heapifyUp(this.data.length - 1);
  }

  pop() {
    if (this.data.length === 0) return undefined;
    if (this.data.length === 1) return this.data.pop();
    const root = this.data[0];
    this.data[0] = this.data.pop();
    this.heapifyDown(0);
    return root;
  }

  peek() {
    return this.data[0];
  }

  heapifyUp(i) {
    while (i &gt; 0) {
      const p = this.parent(i);
      if (this.compare(this.data[i], this.data[p])) {
        this.swap(i, p);
        i = p;
      } else break;
    }
  }

  heapifyDown(i) {
    const n = this.data.length;
    while (true) {
      let best = i;
      const l = this.left(i);
      const r = this.right(i);

      if (l &lt; n &amp;&amp; this.compare(this.data[l], this.data[best])) best = l;
      if (r &lt; n &amp;&amp; this.compare(this.data[r], this.data[best])) best = r;

      if (best !== i) {
        this.swap(i, best);
        i = best;
      } else break;
    }
  }
}

