function subsetsBacktrack(nums) {
  const res = [];

  function backtrack(index, path) {
    res.push([...path]);
    for (let i = index; i &lt; nums.length; i++) {
      path.push(nums[i]);                 // include
      backtrack(i + 1, path);             // recurse
      path.pop();                         // exclude (backtrack)
    }
  }

  backtrack(0, []);
  return res;
}

