var generateParenthesis = function(n) {
  const result = [];

  function backtrack(curr, open, close) {
    if (curr.length === n * 2) {
      result.push(curr);
      return;
    }

    if (open &lt; n) {
      backtrack(curr + &quot;(&quot;, open + 1, close);
    }

    if (close &lt; open) {
      backtrack(curr + &quot;)&quot;, open, close + 1);
    }
  }

  backtrack(&quot;&quot;, 0, 0);
