// Tree Node definition
class Node {
  constructor(value) {
    this.value = value;
    this.children = []; // multiple children allowed (general tree)
  }

  addChild(node) {
    this.children.push(node);
  }
}

// DFS Traversal (recursive)
function dfs(root) {
  const result = [];

  function traverse(node) {
    if (!node) return;
    result.push(node.value); // visit current node
    for (let child of node.children) {
      traverse(child); // recursively visit children
    }
  }

  traverse(root);
  return result;
}

// BFS Traversal (level-order)
function bfs(root) {
  if (!root) return [];

  const result = [];
  const queue = [root];

  while (queue.length &gt; 0) {
    const node = queue.shift();
    result.push(node.value);
    for (let child of node.children) {
      queue.push(child);
    }
  }

  return result;
}

// Height of the tree (max depth)
function height(root) {
  if (!root) return 0;
  if (root.children.length === 0) return 1;

  let maxChildHeight = 0;
  for (let child of root.children) {
    maxChildHeight = Math.max(maxChildHeight, height(child));
  }
  return maxChildHeight + 1; // include current node
}

// Width of the tree (maximum nodes in any level)
function width(root) {
  if (!root) return 0;

  let maxWidth = 0;
  const queue = [root];

  while (queue.length &gt; 0) {
    const levelSize = queue.length;
    maxWidth = Math.max(maxWidth, levelSize);

    for (let i = 0; i &lt; levelSize; i++) {
      const node = queue.shift();
      for (let child of node.children) {
        queue.push(child);
      }
    }
  }

  return maxWidth;
}

